{
  "name": "@resonanceee/agent-police",
  "version": "0.2.0",
  "description": "Opencode plugin: an LLM reviewer judges every bash command the coding agent wants to run (safe / elaborate / human-review) before execution.",
  "license": "MIT",
  "homepage": "https://www.npmjs.com/package/@resonanceee/agent-police",
  "type": "module",
  "main": "./plugin.ts",
  "exports": {
    ".": "./plugin.ts"
  },
  "files": [
    "plugin.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/resonanceee/agent-police.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ai-safety",
    "agent-security",
    "command-review"
  ],
  "scripts": {
    "test": "bun test/harness.ts",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.26",
    "@types/bun": "latest",
    "typescript": "^5"
  },
  "packageManager": "npm@11.17.0+sha512.3eeaf18997b11070d313849268b23766b9db0068997dec9471073170fe43fa17f2b4d0337bf0f52330ee2274e7f5754b21b01052742e48f5c9c74d8b1e32ef43"
}
